class api extends Core { const VERSION = '1.0'; const REALNAME = 'API de lecture (IA)'; const DELETE = true; const DATADIRECTORY = ''; const MULTIMODULE = false; public static $actions = [ 'index' => self::ROLE_VISITOR, 'pages' => self::ROLE_VISITOR, 'content' => self::ROLE_VISITOR, 'search' => self::ROLE_VISITOR, ]; const ARTICLE_MODULES = ['blog', 'news']; const EXCERPT_LENGTH = 400; public function index() { $this->initJsonResponse(); if (!$this->isLlmsAllowed()) { $this->deny(); return; } $language = $this->resolveLanguage(); if ($language['valid'] === false) { $this->error(400, $this->unknownLanguageMessage($language['requested'])); return; } $state = $this->withLanguage($language['lang'], function () { $siteRoot = $this->siteRootUrl(); return [ 'api' => [ 'name' => 'API de lecture pour modèles de langage', 'version' => self::VERSION, 'readOnly' => true, 'format' => 'application/json', 'language' => self::$siteContent, 'languageTag' => $this->languageTag(self::$siteContent), 'defaultLanguage' => $this->defaultLanguage(), 'languageParam' => 'lang', 'languageAlias' => 'l', ], 'site' => [ 'title' => $this->decodeHtml((string) $this->getData(['locale', 'title'])), 'description' => $this->decodeHtml(trim((string) $this->getData(['locale', 'metaDescription']))), 'baseUrl' => $siteRoot, 'languages' => $this->installedLanguages(), ], 'languages' => $this->describeLanguages(), 'endpoints' => [ [ 'method' => 'GET', 'path' => '/api/pages', 'description' => 'Arborescence des pages publiques et de leurs articles publiés. Paramètre optionnel ?lang=<code> ; ?lang=all pour toutes les langues installées.', ], [ 'method' => 'GET', 'path' => '/api/content/<pageId>[/<articleId>]', 'description' => 'Contenu complet d\'une page ou d\'un article. Paramètre optionnel ?lang=<code>.', ], [ 'method' => 'GET', 'path' => '/api/search/<termes>[/<limit>]', 'description' => 'Recherche plein texte dans les pages et articles. Paramètres optionnels ?lang=<code>, ?q=<termes> et ?limit=<n> (1 à 100, 20 par défaut), ou limite en 3e segment (/api/search/<termes>/<n>).', ], ], 'llmsTxt' => $siteRoot . 'llms.txt', ]; }); $this->sendLanguageHeaders($language['lang']); $this->addOutput([ 'display' => self::DISPLAY_JSON, 'content' => $state, ]); } public function pages() { $this->initJsonResponse(); if (!$this->isLlmsAllowed()) { $this->deny(); return; } $language = $this->resolveLanguage(true); if ($language['valid'] === false) { $this->error(400, $this->unknownLanguageMessage($language['requested'], true)); return; } if ($language['all'] === true) { $languages = []; foreach (array_keys($this->installedLanguages()) as $langId) { $languages[$langId] = $this->withLanguage($langId, function () { return $this->pagesState(); }); } $this->sendLanguageHeaders(array_keys($languages)); $this->addOutput([ 'display' => self::DISPLAY_JSON, 'content' => [ 'defaultLanguage' => $this->defaultLanguage(), 'languages' => $languages, ], ]); return; } $result = $this->withLanguage($language['lang'], function () { return $this->pagesState(); }); $this->sendLanguageHeaders($language['lang']); $this->addOutput([ 'display' => self::DISPLAY_JSON, 'content' => $result, ]); } private function pagesState() { return [ 'language' => self::$siteContent, 'languageTag' => $this->languageTag(self::$siteContent), 'isDefaultLanguage' => $this->isCurrentLanguageDefault(), 'baseUrl' => $this->siteRootUrl(), 'pages' => $this->collectPages(), ]; } public function content() { $this->initJsonResponse(); if (!$this->isLlmsAllowed()) { $this->deny(); return; } $path = $this->getRequestString('path'); if ($path === '') { $segments = []; for ($i = 2; $i <= 3; $i++) { $segment = $this->getUrl($i); if ($segment !== null && $segment !== '') { $segments[] = $segment; } } $path = implode('/', $segments); } $path = trim(rawurldecode((string) $path), '/'); if ($path === '') { $this->error(400, 'Paramètre "path" requis (format : <pageId>[/<articleId>]).'); return; } $segments = explode('/', $path); $pageId = $segments[0]; $articleId = $segments[1] ?? null; $language = $this->resolveLanguage(); if ($language['valid'] === false) { $this->error(400, $this->unknownLanguageMessage($language['requested'])); return; } $result = $this->withLanguage($language['lang'], function () use ($pageId, $articleId) { if ($this->getData(['page', $pageId]) === null || !$this->isPagePublic($pageId)) { return null; } $baseUrl = $this->publicBaseUrl(); $langParam = $this->getLanguageQueryParam(self::$siteContent, true); if ($articleId === null) { $content = [ 'type' => 'page', 'language' => self::$siteContent, 'languageTag' => $this->languageTag(self::$siteContent), 'id' => $pageId, 'title' => $this->decodeHtml((string) $this->getData(['page', $pageId, 'title'])), 'url' => $baseUrl . $pageId . $langParam, 'metaDescription' => $this->decodeHtml((string) $this->getData(['page', $pageId, 'metaDescription'])), 'content' => $this->pageContentForApi($pageId), 'articles' => $this->collectPageArticles($pageId), ]; return $content; } $article = $this->findArticle($pageId, $articleId); if ($article === null) { return null; } return [ 'type' => 'article', 'language' => self::$siteContent, 'languageTag' => $this->languageTag(self::$siteContent), 'id' => $articleId, 'pageId' => $pageId, 'title' => $this->decodeHtml((string) ($article['title'] ?? '')), 'url' => $baseUrl . $pageId . '/' . $articleId . $langParam, 'publishedOn' => (int) ($article['publishedOn'] ?? 0), 'publishedOnIso' => $this->isoDate((int) ($article['publishedOn'] ?? 0)), 'content' => $this->cleanHtml(Helper::cleanRssText((string) ($article['content'] ?? ''))), 'excerpt' => $this->excerpt((string) ($article['content'] ?? '')), ]; }); if ($result === null) { $this->error(404, 'Page ou article introuvable ou non public.'); return; } $this->sendLanguageHeaders($language['lang']); $this->addOutput([ 'display' => self::DISPLAY_JSON, 'content' => $result, ]); } public function search() { $this->initJsonResponse(); if (!$this->isLlmsAllowed()) { $this->deny(); return; } $query = trim((string) $this->getRequestString('q')); if ($query === '') { $query = trim((string) $this->getUrl(2)); } $query = trim(rawurldecode($query)); if ($query === '') { $this->error(400, 'Paramètre "q" requis (termes de recherche).'); return; } $limit = (int) $this->getRequestString('limit'); if ($limit <= 0) { $limit = (int) $this->getUrl(3); } $limit = $limit > 0 ? min($limit, 100) : 20; $terms = []; foreach (preg_split('/\s+/', $query) as $term) { if (mb_strlen($term, 'UTF-8') >= 2) { $terms[] = $term; } } if ($terms === []) { $this->error(400, 'Aucun terme de recherche valide (2 caractères minimum).'); return; } $language = $this->resolveLanguage(); if ($language['valid'] === false) { $this->error(400, $this->unknownLanguageMessage($language['requested'])); return; } $result = $this->withLanguage($language['lang'], function () use ($terms, $limit) { $baseUrl = $this->publicBaseUrl(); $langParam = $this->getLanguageQueryParam(self::$siteContent, true); $matches = []; foreach ($this->walkPublicPages() as $pageId) { $pageTitle = $this->decodeHtml((string) $this->getData(['page', $pageId, 'title'])); $pageText = $this->decodeHtml(strip_tags((string) $this->pageContentForApi($pageId))); $score = $this->countMatches($pageTitle . ' ' . $pageText, $terms); if ($score > 0) { $matches[] = [ 'type' => 'page', 'id' => $pageId, 'title' => $pageTitle, 'url' => $baseUrl . $pageId . $langParam, 'excerpt' => $this->snippet($pageText, $terms), 'score' => $score, ]; } foreach ($this->collectPageArticles($pageId) as $article) { $articleData = $this->findArticle($pageId, $article['id']); $articleText = $this->decodeHtml(strip_tags((string) ($articleData['content'] ?? ''))); $articleScore = $this->countMatches($article['title'] . ' ' . $articleText, $terms); if ($articleScore > 0) { $matches[] = [ 'type' => 'article', 'id' => $article['id'], 'pageId' => $pageId, 'title' => $article['title'], 'url' => $article['url'], 'publishedOn' => $article['publishedOn'], 'excerpt' => $this->snippet($articleText, $terms), 'score' => $articleScore, ]; } } } usort($matches, function ($a, $b) { if ($a['score'] === $b['score']) { $dateA = $a['publishedOn'] ?? 0; $dateB = $b['publishedOn'] ?? 0; return $dateB <=> $dateA; } return $b['score'] <=> $a['score']; }); return [ 'language' => self::$siteContent, 'languageTag' => $this->languageTag(self::$siteContent), 'query' => implode(' ', $terms), 'count' => count($matches), 'results' => array_slice($matches, 0, $limit), ]; }); $this->sendLanguageHeaders($language['lang']); $this->addOutput([ 'display' => self::DISPLAY_JSON, 'content' => $result, ]); } private function isLlmsAllowed() { return $this->getData(['config', 'seo', 'llms']) === true; } private function initJsonResponse() { if (headers_sent()) { return; } header_remove('Set-Cookie'); header('Content-Type: application/json; charset=utf-8'); header('Cache-Control: public, max-age=300'); } private function deny() { $this->error(403, 'L\'accès du site aux modèles de langage (IA) est désactivé.'); } private function error($code, $message) { http_response_code($code); $this->addOutput([ 'display' => self::DISPLAY_JSON, 'content' => [ 'error' => [ 'code' => $code, 'message' => $message, ], ], ]); } private function resolveLanguage($allowAll = false) { $requested = ''; foreach (['lang', 'l'] as $param) { $requested = $this->getRequestString($param); if ($requested !== '') { break; } } if ($requested === '') { return [ 'lang' => $this->defaultLanguage(), 'requested' => null, 'valid' => true, 'all' => false, ]; } if ($allowAll === true && strtolower($requested) === 'all') { return [ 'lang' => $this->defaultLanguage(), 'requested' => 'all', 'valid' => true, 'all' => true, ]; } $requested = $this->normalizeLanguageRequest($requested); if (!array_key_exists($requested, $this->installedLanguages())) { return [ 'lang' => $this->defaultLanguage(), 'requested' => $requested, 'valid' => false, 'all' => false, ]; } return [ 'lang' => $requested, 'requested' => $requested, 'valid' => true, 'all' => false, ]; } private function defaultLanguage() { foreach (self::$languages as $langId => $label) { if (is_dir(self::DATA_DIR . $langId) && file_exists(self::DATA_DIR . $langId . '/.default')) { return $langId; } } $installed = $this->installedLanguages(); if (isset($installed[self::$siteContent])) { return self::$siteContent; } return $installed === [] ? self::$siteContent : array_key_first($installed); } private function unknownLanguageMessage($requested, $allowAll = false) { $available = array_keys($this->installedLanguages()); if ($allowAll === true) { $available[] = 'all'; } return 'Langue inconnue : "' . $requested . '". Valeurs acceptées : ' . implode(', ', $available) . '.'; } private function normalizeLanguageRequest($requested) { $requested = (string) $requested; $installed = $this->installedLanguages(); if ($requested === '' || isset($installed[$requested])) { return $requested; } $candidate = str_replace('-', '_', $requested); if (isset($installed[$candidate])) { return $candidate; } $lower = strtolower($candidate); foreach (array_keys($installed) as $langId) { if (strtolower($langId) === $lower) { return $langId; } } $primary = strtolower(explode('_', $lower)[0]); foreach (array_keys($installed) as $langId) { if (strtolower(explode('_', $langId)[0]) === $primary) { return $langId; } } return $requested; } private function isCurrentLanguageDefault() { return file_exists(self::DATA_DIR . self::$siteContent . '/.default'); } private function languageTag($lang) { $tag = str_replace('_', '-', (string) $lang); return $tag === 'en-EN' ? 'en' : $tag; } private function sendLanguageHeaders($langs) { if (headers_sent()) { return; } $tags = []; foreach ((array) $langs as $lang) { $tags[] = $this->languageTag($lang); } if ($tags === []) { return; } header('Content-Language: ' . implode(', ', $tags)); header('Cache-Control: public, max-age=300'); } private function describeLanguages() { $baseUrl = Helper::baseUrl(); $languages = []; foreach ($this->installedLanguages() as $langId => $label) { $languages[$langId] = [ 'label' => $label, 'tag' => $this->languageTag($langId), 'default' => file_exists(self::DATA_DIR . $langId . '/.default'), 'apiPages' => $baseUrl . 'api/pages' . $this->getLanguageQueryParam($langId, true), ]; } return $languages; } private function withLanguage($lang, callable $callback) { $savedSiteContent = self::$siteContent; try { if ($lang !== $savedSiteContent) { self::$siteContent = $lang; $this->jsonDB($lang, ['page', 'module', 'locale']); $this->buildHierarchy(); $this->syncSharedCache(); } return $callback(); } finally { self::$siteContent = $savedSiteContent; $this->jsonDB($savedSiteContent, ['page', 'module', 'locale']); $this->buildHierarchy(); $this->syncSharedCache(); } } private function syncSharedCache() { if (isset($GLOBALS['common_cache'])) { $GLOBALS['common_cache']['siteContent'] = self::$siteContent; $GLOBALS['common_cache']['hierarchy'] = $this->hierarchy; } } private function installedLanguages() { $languages = []; foreach (self::$languages as $langId => $label) { if (is_dir(self::DATA_DIR . $langId)) { $languages[$langId] = $label; } } return $languages; } private function walkPublicPages() { $ordered = []; $visited = []; $walk = function ($pageId, $depth) use (&$walk, &$ordered, &$visited) { if (isset($visited[$pageId]) || $depth > self::getCoreParam('menuDepth', self::MENU_DEPTH)) { return; } $visited[$pageId] = true; if ($this->isPagePublic($pageId)) { $ordered[] = $pageId; } foreach ($this->getHierarchy($pageId, false) as $childId) { $walk($childId, $depth + 1); } }; foreach ($this->getHierarchy(null, false) as $parentId => $children) { if ($this->getData(['page', $parentId, 'parentPageId']) !== '') { continue; } $walk($parentId, 0); } $this->walkOrphans($walk, $visited); return $ordered; } private function walkOrphans(callable $walk, array &$visited) { $known = []; foreach ($this->getHierarchy(null, false) as $parentId => $children) { $known[$parentId] = true; foreach ($children as $childId) { $known[$childId] = true; } } foreach (array_keys($known) as $pageId) { if (!isset($visited[$pageId])) { $walk($pageId, 0); } } } private function collectPages() { $visited = []; $baseUrl = $this->publicBaseUrl(); $langParam = $this->getLanguageQueryParam(self::$siteContent, true); $build = function ($pageId, $depth) use (&$build, &$visited, $baseUrl, $langParam) { if (isset($visited[$pageId]) || $depth > self::getCoreParam('menuDepth', self::MENU_DEPTH)) { return []; } $visited[$pageId] = true; $children = []; foreach ($this->getHierarchy($pageId, false) as $childId) { foreach ($build($childId, $depth + 1) as $childNode) { $children[] = $childNode; } } if (!$this->isPagePublic($pageId)) { return $children; } return [[ 'id' => $pageId, 'title' => $this->decodeHtml((string) $this->getData(['page', $pageId, 'title'])), 'url' => $baseUrl . $pageId . $langParam, 'articles' => $this->collectPageArticles($pageId), 'children' => $children, ]]; }; $tree = []; foreach ($this->getHierarchy(null, false) as $parentId => $children) { if ($this->getData(['page', $parentId, 'parentPageId']) !== '') { continue; } foreach ($build($parentId, 0) as $node) { $tree[] = $node; } } $this->walkOrphans(function ($pageId, $depth) use (&$build, &$tree) { foreach ($build($pageId, $depth) as $node) { $tree[] = $node; } }, $visited); return $tree; } private function isPagePublic($pageId) { return $this->getData(['page', $pageId]) !== null && $this->getData(['page', $pageId, 'role']) === self::ROLE_VISITOR && $this->getData(['page', $pageId, 'block']) !== 'bar' && $this->getData(['page', $pageId, 'disable']) !== true; } private function pageContentForApi($pageId) { $contentFile = (string) $this->getData(['page', $pageId, 'content']); if ($contentFile === '' || !file_exists(self::DATA_DIR . self::$siteContent . '/content/' . $contentFile)) { return ''; } $html = (string) $this->getPage($pageId, self::$siteContent); return $this->cleanHtml(Helper::cleanRssText($html)); } private function collectPageArticles($pageId) { $articles = []; $now = time(); $baseUrl = $this->publicBaseUrl(); $langParam = $this->getLanguageQueryParam(self::$siteContent, true); foreach ($this->getArticleInstances($pageId) as $instanceId) { foreach ((array) $this->getData(['module', $instanceId, 'posts']) as $articleId => $article) { $publishedOn = (int) ($article['publishedOn'] ?? 0); if (($article['state'] ?? false) !== true || $publishedOn > $now) { continue; } $articles[] = [ 'id' => $articleId, 'title' => $this->decodeHtml((string) ($article['title'] ?? '')), 'url' => $baseUrl . $pageId . '/' . $articleId . $langParam, 'publishedOn' => $publishedOn, 'publishedOnIso' => $this->isoDate($publishedOn), 'excerpt' => $this->excerpt((string) ($article['content'] ?? '')), ]; } } usort($articles, function ($a, $b) { return $b['publishedOn'] <=> $a['publishedOn']; }); return $articles; } private function getArticleInstances($pageId) { $page = (array) $this->getData(['page', $pageId]); $instances = []; $pageModules = $page['pageModules'] ?? null; if (is_array($pageModules) && $pageModules !== []) { foreach ($pageModules as $instanceId => $config) { if (in_array($config['moduleId'] ?? '', self::ARTICLE_MODULES, true)) { $instances[] = $instanceId; } } } elseif (!empty($page['moduleId']) && in_array($page['moduleId'], self::ARTICLE_MODULES, true)) { $zone = $page['modulePosition'] ?? 'bottom'; $pageKey = Helper::filter((string) $pageId, Helper::FILTER_ID); $instances[] = $page['moduleId'] . ($pageKey !== '' ? '-' . $pageKey : '') . '-' . $zone; } return $instances; } private function findArticle($pageId, $articleId) { $now = time(); foreach ($this->getArticleInstances($pageId) as $instanceId) { $article = $this->getData(['module', $instanceId, 'posts', $articleId]); if ( is_array($article) && ($article['state'] ?? false) === true && (int) ($article['publishedOn'] ?? 0) <= $now ) { return $article; } } return null; } private function publicBaseUrl() { return Helper::baseUrl(); } private function siteRootUrl() { return rtrim(Helper::baseUrl(false), '/') . '/'; } private function getRequestString($name) { $value = $_GET[$name] ?? $_POST[$name] ?? ''; if (is_array($value)) { return ''; } return trim((string) $value); } private function decodeHtml($text) { return html_entity_decode((string) $text, ENT_QUOTES | ENT_HTML5, 'UTF-8'); } private function cleanHtml($html) { return trim((string) $html); } private function excerpt($html, $maxLength = self::EXCERPT_LENGTH) { $text = $this->decodeHtml(strip_tags(Helper::cleanRssText((string) $html))); $text = trim(preg_replace('/\s+/', ' ', $text)); if ($maxLength > 0 && mb_strlen($text, 'UTF-8') > $maxLength) { $text = mb_substr($text, 0, $maxLength, 'UTF-8'); $lastSpace = mb_strrpos($text, ' ', 0, 'UTF-8'); if ($lastSpace !== false && $lastSpace > 0) { $text = mb_substr($text, 0, $lastSpace, 'UTF-8'); } $text .= '…'; } return $text; } private function snippet($text, $terms, $length = 240) { $text = trim(preg_replace('/\s+/', ' ', (string) $text)); if ($text === '') { return ''; } $position = -1; foreach ($terms as $term) { $found = mb_stripos($text, $term, 0, 'UTF-8'); if ($found !== false && ($position === -1 || $found < $position)) { $position = $found; } } if ($position === -1) { $position = 0; } $start = max(0, $position - 60); $snippet = mb_substr($text, $start, $length, 'UTF-8'); if ($start > 0) { $snippet = '…' . $snippet; } if ($start + $length < mb_strlen($text, 'UTF-8')) { $snippet .= '…'; } return $snippet; } private function countMatches($text, $terms) { $score = 0; foreach ($terms as $term) { $count = @preg_match_all('/' . preg_quote($term, '/') . '/iu', $text); if (is_int($count)) { $score += $count; } } return $score; } private function isoDate($timestamp) { if ($timestamp <= 0) { return ''; } return gmdate('Y-m-d\TH:i:s\Z', $timestamp); } }
